1. /**
2.  * Boot scene: generates all procedural assets and shows a title screen.
3.  */
4. 
5. import * as Phaser from "phaser";
6. import { generateAllTextures, generatePlayerTextureWithHair } from "../renderers/textures";
7. import { PLAYER_CLASSES, type PlayerClass } from "../systems/classes";
8. import { SKIN_COLOR_OPTIONS, HAIR_STYLE_OPTIONS, HAIR_COLOR_OPTIONS, type CustomAppearance } from "../systems/appearance";
9. import { hasSave, loadGame, deleteSave, getSaveSummary } from "../systems/save";
10. import { saveGame } from "../systems/save";
11. import { createCodex } from "../systems/codex";
12. import { createPlayer, type PlayerState, type PlayerStats, POINT_BUY_COSTS, POINT_BUY_TOTAL, calculatePointsSpent } from "../systems/player";
13. import { abilityModifier, rollAbilityScore } from "../systems/dice";
14. import { audioEngine } from "../systems/audio";
15. import { createWeatherState } from "../systems/weather";
16. import { SceneTransitionManager } from "../managers/sceneTransition";
17. import { debugPanelState } from "../config";
18. import { CAMPAIGN_EPILOGUE_CUTSCENE_ID } from "../data/cutscenes";
19. import {
20.   addSettingsControls,
21.   SETTINGS_PANEL_HEIGHT,
22.   SETTINGS_PANEL_WIDTH,
23. } from "../renderers/settings";
24. import {
25.   installSceneAccessibility,
26.   isReducedMotionEnabled,
27. } from "../systems/accessibility";
28. import {
29.   getNewGameCutsceneIds,
30.   getNextPendingCutscene,
31.   queueCutscenes,
32. } from "../systems/cutscenes";
33. import { openMobileTextInput } from "../managers/input";
34. import {
35.   calcPanelLayout,
36.   createDimGraphics,
37.   createOverlayContainer,
38.   createPanelGraphics,
39. } from "../utils/ui";
40. 
41. const BOOT_TEXTURE_MEASURE = "2dnd:boot-textures";
42. const BOOT_TEXTURE_START_MARK = `${BOOT_TEXTURE_MEASURE}:start`;
43. const BOOT_TEXTURE_END_MARK = `${BOOT_TEXTURE_MEASURE}:end`;
44. 
45. export class BootScene extends Phaser.Scene {
46.   private readonly sceneTransitions = new SceneTransitionManager(this);
47. 
48.   constructor() {
49.     super({ key: "BootScene" });
50.   }
51. 
52.   preload(): void {
53.     // No external assets to load - we generate everything procedurally
54.   }
55. 
56.   create(): void {
57.     this.sceneTransitions.prepare();
58.     installSceneAccessibility(this);
59.     performance.clearMeasures(BOOT_TEXTURE_MEASURE);
60.     performance.clearMarks(BOOT_TEXTURE_START_MARK);
61.     performance.clearMarks(BOOT_TEXTURE_END_MARK);
62.     performance.mark(BOOT_TEXTURE_START_MARK);
63.     generateAllTextures(this);
64.     performance.mark(BOOT_TEXTURE_END_MARK);
65.     performance.measure(
66.       BOOT_TEXTURE_MEASURE,
67.       BOOT_TEXTURE_START_MARK,
68.       BOOT_TEXTURE_END_MARK,
69.     );
70.     performance.clearMarks(BOOT_TEXTURE_START_MARK);
71.     performance.clearMarks(BOOT_TEXTURE_END_MARK);
72.     this.showTitleScreen();
73.   }
74. 
75. 
76.   /** Format class info string for the selection panel. */
77.   private formatClassInfo(app: PlayerClass): string {
78.     const boostParts = Object.entries(app.statBoosts)
79.       .map(([k, v]) => `${k.slice(0, 3).toUpperCase()}+${v}`)
80.       .join(", ");
81.     return `${app.playstyle} | ${boostParts} | d${app.hitDie} HP`;
82.   }
83. 
84. 
85.   private showTitleScreen(): void {
86.     debugPanelState("BOOT | Screen: title");
87.     const cx = this.cameras.main.centerX;
88.     const cy = this.cameras.main.centerY;
89. 
90.     this.cameras.main.setBackgroundColor(0x0a0a1a);
91. 
92.     // Initialize audio on first pointer interaction (browsers require user gesture)
93.     this.input.once("pointerdown", () => {
94.       audioEngine.init();
95.       audioEngine.playTitleMusic();
96.     });
97.     // Also initialize on first keyboard press
98.     this.input.keyboard!.once("keydown", () => {
99.       audioEngine.init();
100.       audioEngine.playTitleMusic();
101.     });
102. 
103.     // ── Favicon / Logo: procedurally draw the D20 die ──
104.     const logoSize = 72;
105.     const lx = cx;
106.     const ly = cy - 120;
107.     const logo = this.add.graphics();
108.     // D20 hexagon shape
109.     const pts = [
110.       { x: 0, y: -logoSize / 2 },
111.       { x: logoSize * 0.45, y: -logoSize / 4 },
112.       { x: logoSize * 0.45, y: logoSize / 4 },
113.       { x: 0, y: logoSize / 2 },
114.       { x: -logoSize * 0.45, y: logoSize / 4 },
115.       { x: -logoSize * 0.45, y: -logoSize / 4 },
116.     ];
117.     logo.fillStyle(0x1a1a2e, 1);
118.     logo.beginPath();
119.     logo.moveTo(lx + pts[0].x, ly + pts[0].y);
120.     for (let i = 1; i < pts.length; i++) logo.lineTo(lx + pts[i].x, ly + pts[i].y);
121.     logo.closePath();
122.     logo.fillPath();
123.     logo.lineStyle(2.5, 0xffd700, 1);
124.     logo.beginPath();
125.     logo.moveTo(lx + pts[0].x, ly + pts[0].y);
126.     for (let i = 1; i < pts.length; i++) logo.lineTo(lx + pts[i].x, ly + pts[i].y);
127.     logo.closePath();
128.     logo.strokePath();
129.     // Inner facet lines
130.     logo.lineStyle(1, 0xffd700, 0.4);
131.     logo.lineBetween(lx + pts[0].x, ly + pts[0].y, lx + pts[3].x, ly + pts[3].y);
132.     logo.lineBetween(lx + pts[5].x, ly + pts[5].y, lx + pts[2].x, ly + pts[2].y);
133.     logo.lineBetween(lx + pts[4].x, ly + pts[4].y, lx + pts[1].x, ly + pts[1].y);
134.     // "2D" text on the die
135.     this.add.text(lx, ly + 4, "2D", {
136.       fontSize: "24px", fontFamily: "monospace", fontStyle: "bold", color: "#ffd700",
137.     }).setOrigin(0.5);
138. 
