         const danger = getQuestDangerState(player, {
           type: "city",
           id: city.id,
         });
         const locked = !access.allowed;
         const color = here || locked ? "#666" : "#ccffcc";
         const label = here
           ? `${city.name} (here)`
           : locked
             ? `${city.name} (sealed)`
             : danger
               ? `${city.name} (!)`
               : city.name;
         const btn = this.scene.add.text(px + panelW / 2, cy, label, {
           fontSize: "11px", fontFamily: "monospace", color,
         }).setOrigin(0.5, 0).setInteractive({ useHandCursor: !here });

         if (!here) {
           btn.on("pointerover", () => btn.setColor("#ffd700"));
           btn.on("pointerout", () => btn.setColor(color));
           let dangerConfirmed = danger?.seen ?? true;
           btn.on("pointerdown", () => {
             if (locked) {
               this.callbacks.showMessage(
                 access.message ?? `${city.name} is sealed by quest progression.`,
                 "#ff6f91",
               );
               return;
             }
             if (danger && !dangerConfirmed) {
               dangerConfirmed = true;
               markQuestWarningSeen(player, danger.id);
               this.callbacks.autoSave();
               this.callbacks.showMessage(
                 `${danger.warning} Select ${city.name} again to confirm travel.`,
                 "#ffb74d",
               );
               return;
             }
             player.mp -= this.pendingTeleportCost;
             player.position.chunkX = city.chunkX;
             player.position.chunkY = city.chunkY;
             player.position.x = city.tileX;
             player.position.y = city.tileY;
             if (player.position.inDungeon) {
               player.position.inDungeon = false;
               player.position.dungeonId = "";
               player.position.dungeonLevel = 0;
             }
             if (player.position.inCity) { player.position.inCity = false; player.position.cityId = ""; player.position.cityChunkIndex = 0; }
             this.dismissTownPicker();
             audioEngine.playTeleportSFX();
             this.callbacks.showMessage(`Teleported to ${city.name}!`, "#88ff88");
             this.callbacks.renderMap();
             this.callbacks.applyDayNightTint();
             this.callbacks.createPlayer();
             this.callbacks.updateHUD();
             this.callbacks.autoSave();
           });
         }
         container.add(btn);
         cy += 20;
       }
     }

     const hint = this.scene.add.text(px + panelW / 2, py + panelH - 14, "Click outside to cancel", {
       fontSize: "9px", fontFamily: "monospace", color: "#666",
     }).setOrigin(0.5, 1);
     container.add(hint);

     this.townPickerOverlay = container;
