   if (value instanceof Error) return value.stack ?? value.message;
   return String(value);
 };
 const handleRendererError = (event: ErrorEvent): void => {
   window.desktop?.reportError(
     `Unhandled error: ${formatRendererError(event.error ?? event.message)}`,
   );
 };
 const handleRendererRejection = (event: PromiseRejectionEvent): void => {
   window.desktop?.reportError(
     `Unhandled rejection: ${formatRendererError(event.reason)}`,
   );
 };
 window.addEventListener("error", handleRendererError);
 window.addEventListener("unhandledrejection", handleRendererRejection);
 window.addEventListener("beforeunload", () => {
   window.removeEventListener("error", handleRendererError);
   window.removeEventListener("unhandledrejection", handleRendererRejection);
   disposeDesktopListener?.();
   semanticInput.destroy();
 }, { once: true });

 const controlsToggle = document.getElementById(
   "controls-toggle",
 ) as HTMLButtonElement | null;
 const controlsPanel = document.getElementById("controls-panel");
 controlsToggle?.addEventListener("click", () => {
   controlsPanel?.classList.toggle("collapsed");
   const collapsed = controlsPanel?.classList.contains("collapsed") ?? true;
   controlsToggle.textContent = collapsed ? "?" : "? Controls";
   controlsToggle.setAttribute("aria-expanded", String(!collapsed));
   controlsToggle.setAttribute(
     "title",
     collapsed ? "Show keyboard controls" : "Hide keyboard controls",
   );
 });

 const desktopFullscreen = document.getElementById(
   "desktop-fullscreen",
 ) as HTMLButtonElement | null;
 if (window.desktop && desktopFullscreen) {
   desktopFullscreen.style.display = "block";
   const updateFullscreenLabel = (isFullscreen: boolean): void => {
     desktopFullscreen.textContent = isFullscreen
       ? "Windowed (F11)"
       : "Fullscreen (F11)";
     desktopFullscreen.setAttribute("aria-pressed", String(isFullscreen));
   };
   window.desktop.getState()
     .then((state) => updateFullscreenLabel(state.isFullscreen))
     .catch((error: unknown) => {
       desktopFullscreen.disabled = true;
       desktopFullscreen.title = "Fullscreen control unavailable";
       debugLog("[desktop] Failed to read window state", error);
     });
   const toggleFullscreen = (): void => {
     window.desktop?.toggleFullscreen()
       .then(updateFullscreenLabel)
       .catch((error: unknown) => {
         debugLog("[desktop] Failed to toggle fullscreen", error);
       });
   };
   const handleFullscreenShortcut = (event: KeyboardEvent): void => {
     if (event.key !== "F11") return;
     event.preventDefault();
     toggleFullscreen();
   };
   desktopFullscreen.addEventListener("click", toggleFullscreen);
   document.addEventListener("keydown", handleFullscreenShortcut);
   const disposeFullscreenChange = window.desktop.onFullscreenChanged(
     updateFullscreenLabel,
   );
   disposeDesktopListener = () => {
     disposeFullscreenChange();
     desktopFullscreen.removeEventListener("click", toggleFullscreen);
     document.removeEventListener("keydown", handleFullscreenShortcut);
   };
 }

 // Wire up the HTML debug toggle (local dev only)
 const debugToggle = document.getElementById("debug-toggle") as HTMLElement | null;
 const checkbox = document.getElementById("debug-checkbox") as HTMLInputElement | null;
 const label = document.getElementById("debug-label") as HTMLElement | null;
 const panel = document.getElementById("debug-panel") as HTMLElement | null;

 const debugCheatsSection = document.getElementById("debug-cheats") as HTMLElement | null;

 if (!isLocalDev()) {
   // Hide all debug UI on production (github.io)
   if (debugToggle) debugToggle.style.display = "none";
   if (panel) panel.style.display = "none";
 } else {
   if (checkbox) {
     checkbox.checked = isDebug();
     // Blur on change so that pressing SPACE to start the game doesn't
     // accidentally toggle the checkbox off.
     checkbox.addEventListener("change", () => {
       const on = toggleDebug();
       checkbox.checked = on;
       checkbox.blur();
       if (label) label.style.color = on ? "#00ff00" : "#555";
       if (panel) panel.style.display = on ? "block" : "none";
       if (debugCheatsSection) debugCheatsSection.style.display = on ? "block" : "none";
     });
     onDebugChanged((on) => {
       checkbox.checked = on;
       if (label) label.style.color = on ? "#00ff00" : "#555";
       if (panel) panel.style.display = on ? "block" : "none";
       if (debugCheatsSection) debugCheatsSection.style.display = on ? "block" : "none";
     });
     // Sync initial state in case debug was already on
     if (isDebug()) {
       if (label) label.style.color = "#00ff00";
       if (panel) panel.style.display = "block";
       if (debugCheatsSection) debugCheatsSection.style.display = "block";
     }
   }

   // Initialize debug command textbox
   initDebugCommandInput();
 }

 // Clicking on the game canvas should blur the debug command input
 // so that Phaser regains keyboard focus
 const gameContainer = document.getElementById("game-container");
 const debugCmd = document.getElementById("debug-cmd") as HTMLInputElement | null;
 if (gameContainer && debugCmd) {
   gameContainer.addEventListener("pointerdown", () => {
     if (document.activeElement === debugCmd) {
       debugCmd.blur();
     }
   });
 }

