489.   private keyCodeFor(code: string): number {
490.     const fixed: Readonly<Record<string, number>> = {
491.       Backspace: 8,
492.       Tab: 9,
493.       Enter: 13,
494.       Escape: 27,
495.       Space: 32,
496.       PageUp: 33,
497.       PageDown: 34,
498.       End: 35,
499.       Home: 36,
500.       ArrowLeft: 37,
501.       ArrowUp: 38,
502.       ArrowRight: 39,
503.       ArrowDown: 40,
504.       F1: 112,
505.       Slash: 191,
506.     };
507.     if (fixed[code] !== undefined) return fixed[code];
508.     if (code.startsWith("Key") && code.length === 4) {
509.       return code.charCodeAt(3);
510.     }
511.     return 0;
512.   }
