+/** Copy one independent campaign snapshot into another stable slot. */
+export function copySaveSlot(
+  sourceSlotId: SaveSlotId,
+  targetSlotId: SaveSlotId,
+  overwrite = false,
+): SaveActionResult {
+  if (sourceSlotId === targetSlotId) {
+    return storageFailure("invalid", "Choose a different destination slot.");
+  }
+  const source = readSaveSlot(sourceSlotId);
+  if (!source) {
+    return storageFailure("not-found", `${sourceSlotId} has no valid campaign.`);
+  }
+  source.timestamp = Date.now();
+  const adapter = getStorageAdapter();
+  const sourceName = adapter?.getName(sourceSlotId);
+  return writeSaveDataToSlot(targetSlotId, source, {
+    overwrite,
