+  const minutes = totalMinutes % 60;
+  return `${hours}h ${String(minutes).padStart(2, "0")}m`;
+}
+
+export {
+  MANUAL_SAVE_SLOT_IDS,
+  SAVE_SLOT_IDS,
+  getSaveSlotStorageKey,
+  type SaveSlotId,
+};
