 export function formatSavePlaytime(playtimeSeconds: number): string {
   const totalMinutes = Math.floor(Math.max(0, playtimeSeconds) / 60);
   const hours = Math.floor(totalMinutes / 60);
   const minutes = totalMinutes % 60;
   return `${hours}h ${String(minutes).padStart(2, "0")}m`;
 }

 /** Get a brief summary of one save for the title screen. */
 export function getSaveSummary(slotId: SaveSlotId = "autosave"): string | null {
   const slot = listSaveSlots().find((entry) => entry.slotId === slotId);
   const metadata = slot?.metadata;
   if (!metadata) return null;
   const date = new Date(metadata.savedAt);
   const dateStr = `${date.getMonth() + 1}/${date.getDate()} ${date.getHours()}:${String(date.getMinutes()).padStart(2, "0")}`;
   return `${metadata.characterName} Lv.${metadata.level} ${metadata.className} | ${metadata.location} | ${dateStr}`;
 }

