 export function readSaveSlotData(slotId: SaveSlotId): SaveData | null {
   const storage = getSaveStorage();
   const adapter = getStorageAdapter();
   if (!storage || !adapter) return null;
   ensureSaveStorageMigrated(storage, adapter);
   const result = adapter.read(slotId, decodeStoredSave);
   if (!result.ok) {
     if (result.error.code !== "missing") {
       debugLog(`[save] Failed to load ${slotId}: ${result.error.message}`);
     }
     return null;
   }
   if (result.recoveryError) {
     debugLog(`[save] ${result.recoveryError.message}`);
   } else if (result.recovered) {
     debugLog(`[save] Recovered ${slotId} from ${result.source}.`);
   }
   return result.value;
 }

 /** Load one campaign slot through the shared schema normalizer. */
 export function loadGame(slotId: SaveSlotId = "autosave"): SaveData | null {
   const data = readSaveSlotData(slotId);
   if (data) beginPlaytimeSession(data);
   return data;
 }

 /** List autosave and every manual slot without changing the active campaign. */
 export function listSaveSlots(): SaveSlotInfo[] {
   const storage = getSaveStorage();
   const adapter = getStorageAdapter();
   if (!storage || !adapter) {
     return SAVE_SLOT_IDS.map((slotId) => ({
       slotId,
       kind: slotId === "autosave" ? "autosave" : "manual",
       state: "unavailable",
       displayName: slotDisplayName(slotId),
       diagnostic: "Local campaign storage is unavailable.",
     }));
   }
   ensureLegacyStorageMigrated(storage, adapter);
   return SAVE_SLOT_IDS.map((slotId) => getSlotInfo(slotId, adapter));
 }

 /** Check whether a valid campaign exists in one slot. */
 export function hasSave(slotId: SaveSlotId = "autosave"): boolean {
   return listSaveSlots().some(
     (slot) => slot.slotId === slotId && slot.state === "valid",
   );
 }

 /** Delete one slot without touching any other campaign. */
 export function deleteSave(slotId: SaveSlotId = "autosave"): SaveActionResult {
   const storage = getSaveStorage();
   const adapter = getStorageAdapter();
   if (!storage || !adapter) {
     return storageFailure(
       "unavailable",
       "Local campaign storage is unavailable.",
     );
   }
   const deleted = adapter.delete(slotId);
   if (!deleted.ok) {
     return storageFailure(deleted.error.code, deleted.error.message);
   }
   if (slotId === "autosave") {
     playtimeSession = null;
     markLegacyMigrationVerified(storage);
   }
   return {
     ok: true,
     message: `${slotDisplayName(slotId)} deleted.`,
   };
 }

 /** Clear all campaign slots and migration bookkeeping. */
 export function deleteAllSaveSlots(): SaveActionResult {
   const storage = getSaveStorage();
   const adapter = getStorageAdapter();
   if (!storage || !adapter) {
     return storageFailure(
       "unavailable",
       "Local campaign storage is unavailable.",
     );
   }
   for (const slotId of SAVE_SLOT_IDS) {
     const result = adapter.delete(slotId);
     if (!result.ok) {
       return storageFailure(result.error.code, result.error.message);
     }
   }
   try {
     storage.removeItem(SAVE_SLOT_MIGRATION_KEY);
     playtimeSession = null;
     return { ok: true, message: "All campaign slots deleted." };
   } catch (error: unknown) {
     return storageFailure(
       "unavailable",
       `Campaign slots were cleared, but migration state could not be reset: ${String(error)}`,
     );
   }
 }

 /** Rename one manual slot without rewriting its campaign payload. */
 export function renameSaveSlot(
   slotId: SaveSlotId,
   name: string,
 ): SaveActionResult {
   if (slotId === "autosave") {
     return storageFailure("unsupported", "The Autosave slot cannot be renamed.");
   }
   const normalized = normalizeSlotName(name);
   if (!normalized) {
     return storageFailure("invalid-name", "Enter a non-empty slot name.");
   }
   const adapter = getStorageAdapter();
   if (!adapter) {
     return storageFailure(
       "unavailable",
       "Local campaign storage is unavailable.",
     );
   }
   const slot = adapter.read(slotId, decodeSaveRaw);
   if (!slot.ok) {
     return storageFailure(
       slot.error.code === "missing" ? "not-found" : slot.error.code,
       slot.error.message,
     );
   }
   const result = adapter.setName(slotId, normalized);
   return result.ok
     ? { ok: true, message: `Renamed ${slotId} to ${normalized}.` }
     : storageFailure(result.error.code, result.error.message);
 }

 /** Copy one independent campaign snapshot into another stable slot. */
 export function copySaveSlot(
   sourceSlotId: SaveSlotId,
   targetSlotId: SaveSlotId,
   overwrite = false,
 ): SaveActionResult {
   if (sourceSlotId === targetSlotId) {
     return storageFailure("invalid", "Choose a different destination slot.");
