result.content:
1. export const SAVE_SLOT_IDS = [
2.   "autosave",
3.   "manual-1",
4.   "manual-2",
5.   "manual-3",
6. ] as const;
7. 
8. export type SaveSlotId = (typeof SAVE_SLOT_IDS)[number];
9. 
10. export const MANUAL_SAVE_SLOT_IDS = [
11.   "manual-1",
12.   "manual-2",
13.   "manual-3",
14. ] as const satisfies readonly SaveSlotId[];
15. 
16. export const LEGACY_SAVE_STORAGE_KEY = "2dnd_save";
17. export const SAVE_SLOT_MIGRATION_KEY = "2dnd_save_slots_migrated_v1";
18. 
19. export interface SaveKeyValueStorage {
20.   getItem(key: string): string | null;
21.   setItem(key: string, value: string): void;
22.   removeItem(key: string): void;
23. }
24. 
25. export type SaveStorageErrorCode =
26.   | "missing"
27.   | "corrupt"
28.   | "invalid"
29.   | "quota"
30.   | "unavailable"
31.   | "verification";
32. 
33. export interface SaveStorageError {
34.   code: SaveStorageErrorCode;
35.   message: string;
36. }
37. 
38. export type SaveStorageWriteResult =
39.   | { ok: true }
40.   | { ok: false; error: SaveStorageError; previousValuePreserved: boolean };
41. 
42. export type SaveStorageReadResult<T> =
43.   | {
44.     ok: true;
45.     value: T;
46.     raw: string;
47.     source: "primary" | "staging" | "backup";
48.     recovered: boolean;
49.     recoveryError?: SaveStorageError;
50.   }
51.   | {
52.     ok: false;
53.     error: SaveStorageError;
54.     present: boolean;
55.   };
56. 
57. export function isSaveSlotId(value: unknown): value is SaveSlotId {
58.   return typeof value === "string"
59.     && (SAVE_SLOT_IDS as readonly string[]).includes(value);
60. }
61. 
62. export function getSaveSlotStorageKey(slotId: SaveSlotId): string {
63.   return slotId === "autosave"
64.     ? LEGACY_SAVE_STORAGE_KEY
65.     : `2dnd_save_slot_${slotId}`;
66. }
67. 
68. export function getSaveSlotBackupKey(slotId: SaveSlotId): string {
69.   return `${getSaveSlotStorageKey(slotId)}:backup`;
70. }
71. 
72. export function getSaveSlotStagingKey(slotId: SaveSlotId): string {
73.   return `${getSaveSlotStorageKey(slotId)}:staging`;
74. }
75. 
76. export function getSaveSlotNameKey(slotId: SaveSlotId): string {
77.   return `${getSaveSlotStorageKey(slotId)}:name`;
78. }
79. 
80. function describeError(error: unknown): string {
81.   return error instanceof Error ? error.message : String(error);
82. }
83. 
84. function classifyStorageError(error: unknown, action: string): SaveStorageError {
85.   const name = typeof error === "object"
86.       && error !== null
87.       && "name" in error
88.       && typeof error.name === "string"
89.     ? error.name
90.     : "";
91.   const quota = name === "QuotaExceededError"
92.     || name === "NS_ERROR_DOM_QUOTA_REACHED";
93.   return {
94.     code: quota ? "quota" : "unavailable",
95.     message: quota
96.       ? `${action} failed because local save storage is full.`
97.       : `${action} failed: ${describeError(error)}`,
98.   };
99. }
100. 
101. export class SaveSlotStorageAdapter {
102.   constructor(private readonly storage: SaveKeyValueStorage) {}
103. 
104.   read<T>(
105.     slotId: SaveSlotId,
106.     decode: (raw: string) => T | null,
107.   ): SaveStorageReadResult<T> {
108.     const candidates: ReadonlyArray<{
109.       source: "primary" | "staging" | "backup";
110.       key: string;
111.     }> = [
112.       { source: "primary", key: getSaveSlotStorageKey(slotId) },
113.       { source: "staging", key: getSaveSlotStagingKey(slotId) },
114.       { source: "backup", key: getSaveSlotBackupKey(slotId) },
115.     ];
116.     let present = false;
117. 
118.     for (const candidate of candidates) {
119.       let raw: string | null;
120.       try {
121.         raw = this.storage.getItem(candidate.key);
122.       } catch (error: unknown) {
123.         return {
124.           ok: false,
125.           error: classifyStorageError(error, `Reading ${slotId}`),
126.           present,
127.         };
128.       }
129.       if (raw === null) continue;
130.       present = true;
131. 
132.       let value: T | null = null;
133.       try {
134.         value = decode(raw);
135.       } catch {
136.         value = null;
137.       }
138.       if (value === null) continue;
139. 
140.       if (candidate.source === "primary") {
141.         return {
142.           ok: true,
143.           value,
144.           raw,
145.           source: candidate.source,
146.           recovered: false,
147.         };
148.       }
149. 
150.       const recoveryError = this.restorePrimary(slotId, raw);
151.       return {
152.         ok: true,
153.         value,
154.         raw,
155.         source: candidate.source,
156.         recovered: true,
157.         ...(recoveryError ? { recoveryError } : {}),
158.       };
159.     }
160. 
161.     return {
162.       ok: false,
163.       error: {
164.         code: present ? "corrupt" : "missing",
165.         message: present
166.           ? `${slotId} and its recovery copies are corrupt.`
167.           : `${slotId} is empty.`,
168.       },
169.       present,
170.     };
171.   }
172. 
173.   write<T>(
174.     slotId: SaveSlotId,
175.     raw: string,
176.     decode: (candidate: string) => T | null,
177.   ): SaveStorageWriteResult {
178.     let decoded: T | null;
179.     try {
180.       decoded = decode(raw);
181.     } catch {
182.       decoded = null;
183.     }
184.     if (decoded === null) {
185.       return {
186.         ok: false,
187.         error: {
188.           code: "invalid",
189.           message: `Refused to write invalid data to ${slotId}.`,
190.         },
191.         previousValuePreserved: true,
192.       };
193.     }
194. 
195.     const primaryKey = getSaveSlotStorageKey(slotId);
196.     const stagingKey = getSaveSlotStagingKey(slotId);
197.     const backupKey = getSaveSlotBackupKey(slotId);
198.     let previous: string | null = null;
199.     let primaryChanged = false;
200. 
201.     try {
202.       previous = this.storage.getItem(primaryKey);
203.       this.storage.setItem(stagingKey, raw);
204.       const staged = this.storage.getItem(stagingKey);
205.       if (staged !== raw || decode(staged) === null) {
206.         return this.rollbackWrite(
207.           slotId,
208.           previous,
209.           primaryChanged,
210.           {
211.             code: "verification",
212.             message: `Could not verify staged data for ${slotId}.`,
213.           },
214.         );
215.       }
216. 
217.       if (previous !== null && decode(previous) !== null) {
218.         this.storage.setItem(backupKey, previous);
219.       }
220. 
221.       this.storage.setItem(primaryKey, raw);
222.       primaryChanged = true;
223.       const written = this.storage.getItem(primaryKey);
224.       if (written !== raw || decode(written) === null) {
225.         return this.rollbackWrite(
226.           slotId,
227.           previous,
228.           primaryChanged,
229.           {
230.             code: "verification",
231.             message: `Could not verify saved data for ${slotId}.`,
232.           },
233.         );
234.       }
235.       this.storage.removeItem(stagingKey);
236.       return { ok: true };
237.     } catch (error: unknown) {
238.       return this.rollbackWrite(
239.         slotId,
240.         previous,
241.         primaryChanged,
242.         classifyStorageError(error, `Writing ${slotId}`),
243.       );
244.     }
245.   }
246. 
247.   delete(slotId: SaveSlotId): SaveStorageWriteResult {
248.     const keys = [
249.       getSaveSlotStorageKey(slotId),
250.       getSaveSlotStagingKey(slotId),
251.       getSaveSlotBackupKey(slotId),
252.       getSaveSlotNameKey(slotId),
253.     ];
254.     try {
255.       for (const key of keys) this.storage.removeItem(key);
256.       return { ok: true };
257.     } catch (error: unknown) {
258.       return {
259.         ok: false,
260.         error: classifyStorageError(error, `Deleting ${slotId}`),
261.         previousValuePreserved: true,
262.       };
263.     }
264.   }
265. 
266.   getName(slotId: SaveSlotId): string | null {
267.     try {
268.       const value = this.storage.getItem(getSaveSlotNameKey(slotId));
269.       return value?.trim() ? value : null;
270.     } catch {
271.       return null;
272.     }
273.   }
274. 
275.   setName(slotId: SaveSlotId, name: string): SaveStorageWriteResult {
276.     try {
277.       const key = getSaveSlotNameKey(slotId);
278.       if (name.length === 0) {
279.         this.storage.removeItem(key);
280.       } else {
281.         this.storage.setItem(key, name);
282.         if (this.storage.getItem(key) !== name) {
283.           return {
284.             ok: false,
285.             error: {
286.               code: "verification",
287.               message: `Could not verify the name for ${slotId}.`,
288.             },
289.             previousValuePreserved: false,
290.           };
291.         }
292.       }
293.       return { ok: true };
294.     } catch (error: unknown) {
295.       return {
296.         ok: false,
297.         error: classifyStorageError(error, `Renaming ${slotId}`),
298.         previousValuePreserved: true,
299.       };
300.     }
301.   }
302. 
303.   private restorePrimary(
304.     slotId: SaveSlotId,
305.     raw: string,
306.   ): SaveStorageError | undefined {
307.     try {
308.       this.storage.setItem(getSaveSlotStorageKey(slotId), raw);
309.       this.storage.removeItem(getSaveSlotStagingKey(slotId));
310.       return undefined;
311.     } catch (error: unknown) {
312.       return classifyStorageError(error, `Recovering ${slotId}`);
313.     }
314.   }
315. 
316.   private rollbackWrite(
317.     slotId: SaveSlotId,
318.     previous: string | null,
319.     primaryChanged: boolean,
320.     error: SaveStorageError,
321.   ): SaveStorageWriteResult {
322.     let previousValuePreserved = !primaryChanged;
323.     try {
324.       if (primaryChanged) {
325.         if (previous === null) {
326.           this.storage.removeItem(getSaveSlotStorageKey(slotId));
327.         } else {
328.           this.storage.setItem(getSaveSlotStorageKey(slotId), previous);
329.         }
330.         previousValuePreserved = true;
331.       }
332.       this.storage.removeItem(getSaveSlotStagingKey(slotId));
333.     } catch {
334.       previousValuePreserved = false;
335.     }
336.     return { ok: false, error, previousValuePreserved };
337.   }
338. }
339.

