1. import { debugLog } from "../config";
2. import { CAMPAIGN_EPILOGUE_CUTSCENE_ID } from "../data/cutscenes";
3. import {
4.   getChunk,
5.   getCity,
6.   getDungeon,
7. } from "../data/map";
8. import { MAIN_QUEST_ID } from "../data/quests";
9. import {
10.   getSeaZone,
11.   getSeaZoneAt,
12. } from "../data/nautical";
13. import { getPlayerClass } from "./classes";
14. import type { CodexData } from "./codex";
15. import type { PlayerState } from "./player";
16. import { isQuestCompleted } from "./quests";
17. import {
18.   createCurrentSaveData,
19.   decodeStoredSave,
20.   ensureSaveStorageMigrated,
21.   normalizeSaveData,
22.   persistSaveData,
23.   readSaveSlotData,
24.   reportSaveFailure,
25.   type SaveActionErrorCode,
26.   type SaveActionResult,
27.   type SaveData,
28. } from "./save";
29. import {
30.   MANUAL_SAVE_SLOT_IDS,
31.   SAVE_SLOT_IDS,
32.   SaveSlotStorageAdapter,
33.   getSaveSlotStorageKey,
34.   type SaveSlotId,
35. } from "./saveStorage";
36. import type { WeatherState } from "./weather";
37. 
38. const SAVE_EXPORT_FORMAT = "2dnd-save-slot";
39. const SAVE_EXPORT_VERSION = 1;
40. const MAX_SLOT_NAME_LENGTH = 24;
41. 
42. export type SaveSlotState = "empty" | "valid" | "corrupt" | "unavailable";
43. export type SaveCampaignStatus = "Prologue" | "In progress" | "Complete" | "Post-game";
44. 
45. export interface SaveSlotMetadata {
46.   slotId: SaveSlotId;
47.   slotName: string;
48.   characterName: string;
49.   classId: string;
50.   className: string;
51.   level: number;
52.   location: string;
53.   campaignStatus: SaveCampaignStatus;
54.   schemaVersion: number;
55.   savedAt: number;
56.   playtimeSeconds: number;
57. }
58. 
59. export interface SaveSlotInfo {
60.   slotId: SaveSlotId;
61.   kind: "autosave" | "manual";
62.   state: SaveSlotState;
63.   displayName: string;
64.   metadata?: SaveSlotMetadata;
65.   diagnostic?: string;
66.   recovered?: boolean;
67. }
68. 
69. export interface SaveToSlotOptions {
70.   overwrite?: boolean;
71.   name?: string;
72. }
73. 
74. export type SaveExportResult =
75.   | { ok: true; fileName: string; json: string }
76.   | { ok: false; code: SaveActionErrorCode; message: string };
77. 
78. function getStorageAdapter(): SaveSlotStorageAdapter | null {
79.   return typeof localStorage === "undefined"
80.     ? null
81.     : new SaveSlotStorageAdapter(localStorage);
82. }
83. 
84. function slotDisplayName(
85.   slotId: SaveSlotId,
86.   storedName?: string | null,
87. ): string {
88.   if (slotId === "autosave") return "Autosave";
89.   if (storedName?.trim()) return storedName.trim();
90.   return `Manual ${Number(slotId.slice("manual-".length))}`;
91. }
92. 
93. function deriveCampaignStatus(data: SaveData): SaveCampaignStatus {
94.   if (isQuestCompleted(data.player.progression.quests, MAIN_QUEST_ID)) {
95.     return data.player.progression.seenCutsceneIds.includes(
96.       CAMPAIGN_EPILOGUE_CUTSCENE_ID,
97.     )
98.       ? "Post-game"
99.       : "Complete";
100.   }
101.   const mainQuest = data.player.progression.quests.quests[MAIN_QUEST_ID];
102.   const hasProgress = (mainQuest?.stage ?? 0) > 0
103.     || Object.values(mainQuest?.objectives ?? {}).some((value) => value > 0);
104.   return hasProgress ? "In progress" : "Prologue";
105. }
106. 
107. function deriveSaveLocation(player: PlayerState): string {
108.   if (player.position.inCity) {
109.     return getCity(player.position.cityId)?.name ?? "Unknown city";
110.   }
111.   if (player.position.inDungeon) {
112.     const dungeon = getDungeon(player.position.dungeonId);
113.     return dungeon
114.       ? `${dungeon.name} L${player.position.dungeonLevel + 1}`
115.       : "Unknown dungeon";
116.   }
117.   if (player.progression.nautical.sailing) {
118.     const sea = getSeaZoneAt(
119.       player.position.chunkX,
120.       player.position.chunkY,
121.       player.position.x,
122.       player.position.y,
123.     );
124.     if (sea) return getSeaZone(sea.zoneId).name;
125.   }
126.   return getChunk(player.position.chunkX, player.position.chunkY)?.name
127.     ?? "Unknown lands";
128. }
129. 
130. function deriveSlotMetadata(
131.   slotId: SaveSlotId,
132.   slotName: string,
133.   data: SaveData,
134. ): SaveSlotMetadata {
135.   const playerClass = getPlayerClass(data.player.appearanceId);
136.   return {
137.     slotId,
138.     slotName,
139.     characterName: data.player.name,
140.     classId: playerClass.id,
141.     className: playerClass.label,
142.     level: data.player.level,
143.     location: deriveSaveLocation(data.player),
144.     campaignStatus: deriveCampaignStatus(data),
145.     schemaVersion: data.version,
146.     savedAt: data.timestamp,
147.     playtimeSeconds: data.playtimeSeconds,
148.   };
149. }
150. 
151. function getSlotInfo(
152.   slotId: SaveSlotId,
153.   adapter: SaveSlotStorageAdapter,
154. ): SaveSlotInfo {
155.   const displayName = slotDisplayName(slotId, adapter.getName(slotId));
156.   const result = adapter.read(slotId, decodeStoredSave);
157.   if (!result.ok) {
158.     return {
159.       slotId,
160.       kind: slotId === "autosave" ? "autosave" : "manual",
161.       state: result.error.code === "missing"
162.         ? "empty"
163.         : result.error.code === "corrupt"
164.           ? "corrupt"
165.           : "unavailable",
166.       displayName,
167.       ...(result.error.code === "missing"
168.         ? {}
169.         : { diagnostic: result.error.message }),
170.     };
171.   }
172.   if (result.recoveryError) {
173.     debugLog(`[save] ${result.recoveryError.message}`);
174.   } else if (result.recovered) {
175.     debugLog(`[save] Recovered ${slotId} from ${result.source}.`);
176.   }
177.   return {
178.     slotId,
179.     kind: slotId === "autosave" ? "autosave" : "manual",
180.     state: "valid",
181.     displayName,
182.     metadata: deriveSlotMetadata(slotId, displayName, result.value),
183.     recovered: result.recovered,
184.     ...(result.recoveryError
185.       ? { diagnostic: result.recoveryError.message }
186.       : {}),
187.   };
188. }
189. 
190. function normalizeSlotName(name: string): string | null {
191.   const normalized = name
192.     .replace(/[\u0000-\u001f\u007f]/g, "")
193.     .replace(/\s+/g, " ")
194.     .trim()
195.     .slice(0, MAX_SLOT_NAME_LENGTH);
196.   return normalized.length > 0 ? normalized : null;
197. }
198. 
199. /** Save the current game state to one stable autosave or manual slot. */
200. export function saveGameToSlot(
201.   slotId: SaveSlotId,
202.   player: PlayerState,
203.   defeatedBosses: Set<string>,
204.   codex: CodexData,
205.   appearanceId: string,
206.   timeStep: number = 0,
207.   weatherState?: WeatherState,
208.   options: SaveToSlotOptions = {},
209. ): SaveActionResult {
210.   const adapter = getStorageAdapter();
211.   const data = createCurrentSaveData(
212.     player,
213.     defeatedBosses,
214.     codex,
215.     appearanceId,
216.     timeStep,
217.     weatherState,
218.   );
219.   const result = persistSaveData(
220.     slotId,
221.     data,
222.     slotId === "autosave" || options.overwrite === true,
223.   );
224.   if (!result.ok || slotId === "autosave") return result;
225.   if (!adapter) {
226.     return reportSaveFailure(
227.       "unavailable",
228.       "Campaign saved, but slot naming is unavailable.",
229.     );
230.   }
231.   const requestedName = options.name
232.     ? normalizeSlotName(options.name)
233.     : adapter.getName(slotId);
234.   const name = requestedName ?? data.player.name.slice(0, MAX_SLOT_NAME_LENGTH);
235.   const named = adapter.setName(slotId, name);
236.   const warning = named.ok
237.     ? undefined
238.     : `Campaign saved, but the slot name could not be updated: ${named.error.message}`;
239.   if (warning) debugLog(`[save] ${warning}`);
240.   return {
241.     ok: true,
242.     message: `Saved ${data.player.name} to ${slotDisplayName(slotId, adapter.getName(slotId))}.`,
243.     ...(warning ? { warning } : {}),
244.   };
245. }
246. 
247. /** List autosave and every manual slot without changing the active campaign. */
248. export function listSaveSlots(): SaveSlotInfo[] {
249.   const adapter = getStorageAdapter();
250.   if (!adapter || typeof localStorage === "undefined") {
251.     return SAVE_SLOT_IDS.map((slotId) => ({
252.       slotId,
253.       kind: slotId === "autosave" ? "autosave" : "manual",
254.       state: "unavailable",
255.       displayName: slotDisplayName(slotId),
256.       diagnostic: "Local campaign storage is unavailable.",
257.     }));
258.   }
259.   ensureSaveStorageMigrated(localStorage, adapter);
260.   return SAVE_SLOT_IDS.map((slotId) => getSlotInfo(slotId, adapter));
261. }
262. 
263. /** Rename one manual slot without rewriting its campaign payload. */
264. export function renameSaveSlot(
265.   slotId: SaveSlotId,
266.   name: string,
267. ): SaveActionResult {
268.   if (slotId === "autosave") {
269.     return reportSaveFailure(
270.       "unsupported",
271.       "The Autosave slot cannot be renamed.",
272.     );
273.   }
274.   const normalized = normalizeSlotName(name);
275.   if (!normalized) {
276.     return reportSaveFailure("invalid-name", "Enter a non-empty slot name.");
277.   }
278.   const adapter = getStorageAdapter();
279.   if (!adapter) {
280.     return reportSaveFailure(
281.       "unavailable",
282.       "Local campaign storage is unavailable.",
283.     );
284.   }
285.   const slot = adapter.read(slotId, decodeStoredSave);
286.   if (!slot.ok) {
287.     return reportSaveFailure(
288.       slot.error.code === "missing" ? "not-found" : slot.error.code,
289.       slot.error.message,
290.     );
291.   }
292.   const result = adapter.setName(slotId, normalized);
293.   return result.ok
294.     ? { ok: true, message: `Renamed ${slotId} to ${normalized}.` }
295.     : reportSaveFailure(result.error.code, result.error.message);
296. }
297. 
298. /** Copy one independent campaign snapshot into another stable slot. */
299. export function copySaveSlot(
300.   sourceSlotId: SaveSlotId,
301.   targetSlotId: SaveSlotId,
302.   overwrite = false,
303. ): SaveActionResult {
304.   if (sourceSlotId === targetSlotId) {
305.     return reportSaveFailure(
306.       "invalid",
307.       "Choose a different destination slot.",
308.     );
309.   }
310.   const source = readSaveSlotData(sourceSlotId);
311.   if (!source) {
312.     return reportSaveFailure(
313.       "not-found",
314.       `${sourceSlotId} has no valid campaign.`,
315.     );
316.   }
317.   source.timestamp = Date.now();
318.   const adapter = getStorageAdapter();
319.   const result = persistSaveData(targetSlotId, source, overwrite);
320.   if (!result.ok || targetSlotId === "autosave" || !adapter) return result;
321.   const sourceName = adapter.getName(sourceSlotId);
322.   const name = normalizeSlotName(
323.     sourceName ? `Copy of ${sourceName}` : `Copy of ${source.player.name}`,
324.   ) ?? source.player.name;
325.   const named = adapter.setName(targetSlotId, name);
326.   if (!named.ok) {
327.     return {
328.       ok: true,
329.       message: result.message,
330.       warning: `Campaign copied, but naming failed: ${named.error.message}`,
331.     };
332.   }
333.   return {
334.     ok: true,
335.     message: `Copied ${source.player.name} to ${slotDisplayName(targetSlotId, name)}.`,
336.   };
337. }
338. 
339. function canonicalizeJson(value: unknown): unknown {
340.   if (Array.isArray(value)) return value.map(canonicalizeJson);
341.   if (
342.     typeof value !== "object"
343.     || value === null
344.     || Array.isArray(value)
345.   ) {
346.     return value;
347.   }
348.   const record = value as Record<string, unknown>;
349.   return Object.fromEntries(
350.     Object.keys(record)
351.       .sort((left, right) => left.localeCompare(right))
352.       .map((key) => [key, canonicalizeJson(record[key])]),
353.   );
354. }
355. 
356. /** Export one validated slot as deterministic, standalone JSON. */
357. export function exportSaveSlot(slotId: SaveSlotId): SaveExportResult {
358.   const data = readSaveSlotData(slotId);
359.   if (!data) {
360.     return {
361.       ok: false,
362.       code: "not-found",
363.       message: `${slotDisplayName(slotId)} has no valid campaign to export.`,
364.     };
365.   }
366.   const adapter = getStorageAdapter();
367.   const name = slotDisplayName(slotId, adapter?.getName(slotId));
368.   const document = canonicalizeJson({
369.     format: SAVE_EXPORT_FORMAT,
370.     formatVersion: SAVE_EXPORT_VERSION,
371.     name,
372.     save: data,
373.   });
374.   const safeName = name.toLowerCase().replace(/[^a-z0-9]+/g, "-")
375.     .replace(/^-|-$/g, "") || slotId;
376.   return {
377.     ok: true,
378.     fileName: `2dnd-${safeName}.json`,
379.     json: `${JSON.stringify(document, null, 2)}\n`,
380.   };
381. }
382. 
383. /** Import one validated standalone export or legacy campaign document. */
384. export function importSaveSlot(
385.   slotId: SaveSlotId,
386.   json: string,
387.   overwrite = false,
388. ): SaveActionResult {
389.   let parsed: unknown;
390.   try {
391.     parsed = JSON.parse(json) as unknown;
392.   } catch {
393.     return reportSaveFailure(
394.       "invalid-import",
395.       "The selected file is not valid JSON.",
396.     );
397.   }
398.   const exported = typeof parsed === "object"
399.       && parsed !== null
400.       && !Array.isArray(parsed)
401.       && "format" in parsed
402.       && parsed.format === SAVE_EXPORT_FORMAT
403.       && "formatVersion" in parsed
404.       && parsed.formatVersion === SAVE_EXPORT_VERSION
405.     ? parsed as Record<string, unknown>
406.     : null;
407.   const value = exported?.["save"] ?? parsed;
408.   const data = normalizeSaveData(value);
409.   if (!data) {
410.     return reportSaveFailure(
411.       "invalid-import",
412.       "The selected file is not a supported 2D&D campaign save.",
413.     );
414.   }
415.   const result = persistSaveData(slotId, data, overwrite);
416.   if (!result.ok || slotId === "autosave") return result;
417.   const exportedName = typeof exported?.["name"] === "string"
418.     ? normalizeSlotName(exported["name"])
419.     : null;
420.   const adapter = getStorageAdapter();
421.   if (exportedName && adapter) {
422.     const named = adapter.setName(slotId, exportedName);
423.     if (!named.ok) {
424.       return {
425.         ok: true,
426.         message: result.message,
427.         warning: `Campaign imported, but naming failed: ${named.error.message}`,
428.       };
429.     }
430.   }
431.   return {
432.     ok: true,
433.     message: `Imported ${data.player.name} into ${slotDisplayName(slotId, exportedName)}.`,
434.   };
435. }
436. 
437. export function formatSavePlaytime(playtimeSeconds: number): string {
438.   const totalMinutes = Math.floor(Math.max(0, playtimeSeconds) / 60);
439.   const hours = Math.floor(totalMinutes / 60);
440.   const minutes = totalMinutes % 60;
441.   return `${hours}h ${String(minutes).padStart(2, "0")}m`;
442. }
443. 
444. export {
445.   MANUAL_SAVE_SLOT_IDS,
446.   SAVE_SLOT_IDS,
447.   getSaveSlotStorageKey,
448.   type SaveSlotId,
449. };
450.

