 export type SaveSlotState = "empty" | "valid" | "corrupt" | "unavailable";
 export type SaveCampaignStatus = "Prologue" | "In progress" | "Complete" | "Post-game";

 export interface SaveSlotMetadata {
   slotId: SaveSlotId;
   slotName: string;
   characterName: string;
   classId: string;
   className: string;
