 function slotDisplayName(
   slotId: SaveSlotId,
   storedName?: string | null,
 ): string {
   if (slotId === "autosave") return "Autosave";
   if (storedName?.trim()) return storedName.trim();
   return `Manual ${Number(slotId.slice("manual-".length))}`;
