 function normalizeSlotName(name: string): string | null {
   const normalized = name
     .replace(/[\u0000-\u001f\u007f]/g, "")
     .replace(/\s+/g, " ")
     .trim()
     .slice(0, MAX_SLOT_NAME_LENGTH);
   return normalized.length > 0 ? normalized : null;
