22. import {
23.   layoutResponsiveGrid,
24.   restoreLayoutFocus,
25. } from "../systems/layout";
26. import { syncInteractiveHitArea } from "./layout";
27. import { openMobileTextInput } from "./input";
28. 
29. export type SaveSlotOverlayMode = "load" | "save";
30. 
31. interface SaveSlotManagerCallbacks {
32.   load(slotId: SaveSlotId): void;
33.   save(slotId: SaveSlotId, overwrite: boolean): SaveActionResult;
34.   onStateChange?(): void;
35. }
36. 
37. type SaveSlotAction =
38.   | "load"
39.   | "save"
40.   | "rename"
41.   | "copy"
42.   | "delete"
43.   | "export"
44.   | "import"
45.   | "confirm"
46.   | "cancel"
47.   | "close";
48. 
49. interface PendingConfirmation {
50.   kind: "save" | "copy" | "delete" | "import" | "newGame";
51.   sourceSlotId?: SaveSlotId;
52.   targetSlotId: SaveSlotId;
53. }
54. 
55. const ACTION_LABELS: Readonly<Record<SaveSlotAction, string>> = {
56.   load: "Load",
57.   save: "Save",
58.   rename: "Rename",
59.   copy: "Copy",
60.   delete: "Delete",
61.   export: "Export",
62.   import: "Import",
63.   confirm: "Confirm",
64.   cancel: "Cancel",
65.   close: "Close",
66. };
67. 
68. function formatSavedAt(timestamp: number): string {
69.   const date = new Date(timestamp);
70.   return `${date.getMonth() + 1}/${date.getDate()} `
71.     + `${date.getHours()}:${String(date.getMinutes()).padStart(2, "0")}`;
72. }
73. 
74. function slotStatusText(slot: SaveSlotInfo): string {
75.   const metadata = slot.metadata;
76.   if (metadata) {
77.     return `${metadata.characterName} Lv.${metadata.level} ${metadata.className}\n`
78.       + `${metadata.location} | ${metadata.campaignStatus} | `
79.       + `${formatSavePlaytime(metadata.playtimeSeconds)} | `
80.       + `${formatSavedAt(metadata.savedAt)}`;
81.   }
82.   if (slot.state === "corrupt") {
83.     return `Recovery needed\n${slot.diagnostic ?? "Campaign data is corrupt."}`;
84.   }
85.   if (slot.state === "unavailable") {
86.     return `Storage unavailable\n${slot.diagnostic ?? "Campaign storage cannot be read."}`;
87.   }
88.   return "Empty\nNo campaign stored";
89. }
90. 
91. function actionColor(action: SaveSlotAction): string {
92.   if (action === "delete") return "#ff8a80";
93.   if (action === "confirm") return "#88ff88";
94.   if (action === "cancel" || action === "close") return "#b0bec5";
95.   return "#9fe8ff";
96. }
97. 
98. export class SaveSlotManager {
99.   private container: Phaser.GameObjects.Container | null = null;
100.   private mode: SaveSlotOverlayMode = "load";
101.   private slots: SaveSlotInfo[] = [];
102.   private selectedSlotIndex = 0;
103.   private selectedActionIndex = 0;
104.   private actions: SaveSlotAction[] = [];
105.   private pendingConfirmation: PendingConfirmation | null = null;
106.   private copySourceSlotId: SaveSlotId | null = null;
107.   private status = "";
108.   private statusColor = "#b0bec5";
109.   private liveRegion: HTMLDivElement | null = null;
110.   private importInput: HTMLInputElement | null = null;
111.   private startNewGame: (() => void) | null = null;
112.   private lastHandledKey = "";
113.   private lastHandledAt = Number.NEGATIVE_INFINITY;
114. 
115.   constructor(
116.     private readonly scene: Phaser.Scene,
117.     private readonly callbacks: SaveSlotManagerCallbacks,
118.   ) {}
119. 
120.   open(mode: SaveSlotOverlayMode): void {
121.     this.close();
122.     this.mode = mode;
123.     this.slots = listSaveSlots();
124.     this.selectedSlotIndex = mode === "save"
125.       ? Math.max(0, this.slots.findIndex((slot) => slot.slotId === "manual-1"))
126.       : Math.max(0, this.slots.findIndex((slot) => slot.state === "valid"));
127.     this.selectedActionIndex = 0;
128.     this.pendingConfirmation = null;
129.     this.copySourceSlotId = null;
130.     this.status = "";
131.     this.lastHandledKey = "";
132.     this.lastHandledAt = Number.NEGATIVE_INFINITY;
133.     this.createLiveRegion();
134.     this.scene.input.keyboard?.on("keydown", this.handleKeyDown, this);
135.     this.render();
136.   }
137. 
138.   confirmNewGame(start: () => void): void {
139.     const autosave = listSaveSlots().find((slot) => slot.slotId === "autosave");
140.     if (!autosave || autosave.state === "empty") {
141.       start();
142.       return;
143.     }
144.     this.open("load");
145.     this.selectedSlotIndex = 0;
146.     this.startNewGame = start;
147.     this.pendingConfirmation = {
148.       kind: "newGame",
149.       targetSlotId: "autosave",
150.     };
151.     this.selectedActionIndex = 0;
152.     this.status = "Starting a new campaign will replace Autosave. Manual slots stay safe.";
153.     this.statusColor = "#ffcc80";
154.     this.render();
155.   }
156. 
157.   close(): void {
