1. import { describe, expect, it } from "vitest";
2. import {
3.   SaveSlotStorageAdapter,
4.   getSaveSlotBackupKey,
5.   getSaveSlotStagingKey,
6.   getSaveSlotStorageKey,
7.   type SaveKeyValueStorage,
8. } from "../src/systems/saveStorage";
9. 
10. class MemoryStorage implements SaveKeyValueStorage {
11.   readonly values = new Map<string, string>();
12.   failOnSetKey: string | null = null;
13. 
14.   getItem(key: string): string | null {
15.     return this.values.get(key) ?? null;
16.   }
17. 
18.   setItem(key: string, value: string): void {
19.     if (key === this.failOnSetKey) {
20.       const error = new Error("Storage quota reached");
21.       error.name = "QuotaExceededError";
22.       throw error;
23.     }
24.     this.values.set(key, value);
25.   }
26. 
27.   removeItem(key: string): void {
28.     this.values.delete(key);
29.   }
30. }
31. 
32. const decode = (raw: string): { value: number } | null => {
33.   const parsed: unknown = JSON.parse(raw);
34.   if (
35.     typeof parsed !== "object"
36.     || parsed === null
37.     || !("value" in parsed)
38.     || typeof parsed.value !== "number"
39.   ) {
40.     return null;
41.   }
42.   return { value: parsed.value };
43. };
44. 
45. describe("SaveSlotStorageAdapter", () => {
46.   it("atomically writes a primary document and retains the prior valid backup", () => {
47.     const storage = new MemoryStorage();
48.     const adapter = new SaveSlotStorageAdapter(storage);
49. 
50.     expect(adapter.write("autosave", '{"value":1}', decode)).toEqual({ ok: true });
51.     expect(adapter.write("autosave", '{"value":2}', decode)).toEqual({ ok: true });
52. 
53.     expect(storage.getItem(getSaveSlotStorageKey("autosave"))).toBe('{"value":2}');
54.     expect(storage.getItem(getSaveSlotBackupKey("autosave"))).toBe('{"value":1}');
55.     expect(storage.getItem(getSaveSlotStagingKey("autosave"))).toBeNull();
56.   });
57. 
58.   it("leaves the previous primary untouched when staging fails", () => {
59.     const storage = new MemoryStorage();
60.     const adapter = new SaveSlotStorageAdapter(storage);
61.     expect(adapter.write("manual-1", '{"value":1}', decode)).toEqual({ ok: true });
62.     storage.failOnSetKey = getSaveSlotStagingKey("manual-1");
63. 
64.     const result = adapter.write("manual-1", '{"value":2}', decode);
65. 
66.     expect(result).toMatchObject({
67.       ok: false,
68.       error: { code: "quota" },
69.       previousValuePreserved: true,
70.     });
71.     expect(storage.getItem(getSaveSlotStorageKey("manual-1"))).toBe('{"value":1}');
72.   });
73. 
74.   it("recovers one corrupt primary from its valid backup", () => {
75.     const storage = new MemoryStorage();
76.     const adapter = new SaveSlotStorageAdapter(storage);
77.     storage.setItem(getSaveSlotStorageKey("manual-2"), "{broken");
78.     storage.setItem(getSaveSlotBackupKey("manual-2"), '{"value":7}');
79. 
80.     const result = adapter.read("manual-2", decode);
81. 
82.     expect(result).toMatchObject({
83.       ok: true,
84.       value: { value: 7 },
85.       source: "backup",
86.       recovered: true,
87.     });
88.     expect(storage.getItem(getSaveSlotStorageKey("manual-2"))).toBe('{"value":7}');
89.   });
90. 
91.   it("keeps corruption isolated to the affected slot", () => {
92.     const storage = new MemoryStorage();
93.     const adapter = new SaveSlotStorageAdapter(storage);
94.     storage.setItem(getSaveSlotStorageKey("manual-1"), "{broken");
95.     storage.setItem(getSaveSlotStorageKey("manual-2"), '{"value":9}');
96. 
97.     expect(adapter.read("manual-1", decode)).toMatchObject({
98.       ok: false,
99.       error: { code: "corrupt" },
100.       present: true,
101.     });
102.     expect(adapter.read("manual-2", decode)).toMatchObject({
103.       ok: true,
104.       value: { value: 9 },
105.     });
106.   });
107. 
108.   it("rejects invalid outgoing payloads before touching storage", () => {
109.     const storage = new MemoryStorage();
110.     const adapter = new SaveSlotStorageAdapter(storage);
111. 
112.     const result = adapter.write("manual-3", "{}", decode);
113. 
114.     expect(result).toMatchObject({
115.       ok: false,
116.       error: { code: "invalid" },
117.       previousValuePreserved: true,
118.     });
119.     expect(storage.values.size).toBe(0);
120.   });
121. });
