28. } from "../src/systems/saveSlots";
29. import {
30.   LEGACY_SAVE_STORAGE_KEY,
31.   SAVE_SLOT_MIGRATION_KEY,
32.   getSaveSlotBackupKey,
33. } from "../src/systems/saveStorage";
34. import { createWeatherState } from "../src/systems/weather";
35. 
36. const STATS = {
37.   strength: 10,
38.   dexterity: 10,
39.   constitution: 10,
40.   intelligence: 10,
41.   wisdom: 10,
42.   charisma: 10,
43. };
44. 
45. function createTestPlayer(name: string, classId = "knight"): PlayerState {
46.   return createPlayer(name, STATS, classId);
47. }
48. 
49. describe("multiple save slots", () => {
50.   beforeEach(() => {
51.     vi.useFakeTimers();
52.     vi.setSystemTime(new Date("2026-08-23T12:00:00Z"));
53.     deleteAllSaveSlots();
54.   });
55. 
56.   afterEach(() => {
57.     deleteAllSaveSlots();
58.     vi.useRealTimers();
59.   });
60. 
61.   it("migrates a legacy schema-v17 document into the verified autosave layout once", () => {
62.     const player = createTestPlayer("Legacy Hero");
63.     saveGame(player, new Set(), createCodex(), player.appearanceId);
64.     const current = JSON.parse(
65.       localStorage.getItem(LEGACY_SAVE_STORAGE_KEY)!,
66.     ) as Record<string, unknown>;
67.     current.version = 17;
68.     delete current.playtimeSeconds;
69.     const legacy = JSON.stringify(current);
70.     deleteAllSaveSlots();
71.     localStorage.setItem(LEGACY_SAVE_STORAGE_KEY, legacy);
72. 
73.     const slots = listSaveSlots();
74. 
75.     expect(slots[0]).toMatchObject({
76.       slotId: "autosave",
77.       state: "valid",
78.       metadata: {
79.         characterName: "Legacy Hero",
80.         schemaVersion: SAVE_VERSION,
81.         playtimeSeconds: 0,
82.       },
83.     });
84.     expect(localStorage.getItem(LEGACY_SAVE_STORAGE_KEY)).toBe(legacy);
85.     expect(localStorage.getItem(getSaveSlotBackupKey("autosave"))).toBe(legacy);
86.     expect(localStorage.getItem(SAVE_SLOT_MIGRATION_KEY)).toBe("verified");
87. 
88.     listSaveSlots();
89.     expect(localStorage.getItem(getSaveSlotBackupKey("autosave"))).toBe(legacy);
90.   });
91. 
