     });
     expect(saveGame(
       player,
       new Set(),
       createCodex(),
       player.appearanceId,
     ).ok).toBe(true);
     expect(document.querySelector('[role="alert"]')).toBeNull();
   });

   it("reports an unrecoverable malformed slot without hiding valid campaigns", () => {
     const player = createTestPlayer("Safe");
     saveGameToSlot(
       "manual-2",
