     if (this.overlayManager.menuOverlay) return;
     if (this.chronicleManager?.isOpen()) {
       this.chronicleManager.replaySelected();
       return;
     }
     if (this.partyOverlayManager.isOpen()) {
       this.partyOverlayManager.close();
       return;
     }
